    // A pointer to the object - only one instance can be created for now
    VerovioToolkit.instances = [];


    // If the window object is defined (if we are not within a WebWorker)...
    if ((typeof window !== "undefined") && (window.addEventListener)) {
        // Add a listener that will delete the object (if necessary) when the page is closed
        window.addEventListener("unload", () => {
            VerovioToolkit.instances.forEach((instance) => {
                instance.destroy();
            });
        });
    }

    const LOG_OFF = 0;
    const LOG_ERROR = 1;
    const LOG_WARNING = 2;
    const LOG_INFO = 3;
    const LOG_DEBUG = 4;

    function enableLog(level, VerovioModule) {
        return VerovioModule.cwrap("enableLog", null, ["number"])(level);
    }

    function enableLogToBuffer(value, VerovioModule) {
        return VerovioModule.cwrap("enableLogToBuffer", null, ["number"])(value);
    }

    class VerovioToolkitDefaultModule extends VerovioToolkit {
        constructor(VerovioModule = DefaultVerovioModule) {
            super(VerovioModule);
        }
    }

    function enableLogDefaultModule(level, VerovioModule = DefaultVerovioModule) {
        return enableLog(level, VerovioModule);
    }

    function enableLogToBufferDefaultModule(value, VerovioModule = DefaultVerovioModule) {
        return enableLogToBuffer(value, VerovioModule);
    }

    // Assign Module to window to prevent breaking changes.
    // Deprecated, use verovio.module instead.
    if (typeof window !== "undefined") {
        window.Module = DefaultVerovioModule;
    }

    var prebundleModule = {
        module: DefaultVerovioModule,
        toolkit: VerovioToolkitDefaultModule,
        LOG_OFF,
        LOG_ERROR,
        LOG_WARNING,
        LOG_INFO,
        LOG_DEBUG,
        enableLog: enableLogDefaultModule,
        enableLogToBuffer: enableLogToBufferDefaultModule,
    };

    return prebundleModule;

